from __future__ import annotations

import re
from datetime import date, datetime, timedelta

_MONTH_NAMES = {
    "JAN": 1,
    "FEB": 2,
    "MAR": 3,
    "APR": 4,
    "MAY": 5,
    "JUN": 6,
    "JUL": 7,
    "AUG": 8,
    "SEP": 9,
    "OCT": 10,
    "NOV": 11,
    "DEC": 12,
}

_WEEKDAY_NAMES = {
    "SUN": 0,
    "MON": 1,
    "TUE": 2,
    "WED": 3,
    "THU": 4,
    "FRI": 5,
    "SAT": 6,
}

_NUMBER = re.compile(r"[0-9]+")


def _parse_value(token: str, low: int, high: int, names: dict[str, int] | None,
                 field: str) -> int:
    """Turn one numeric or symbolic field value into an int."""
    if names is not None:
        value = names.get(token.upper())
        if value is not None:
            return value
    if not _NUMBER.fullmatch(token):
        raise ValueError(f"invalid {field} value: {token!r}")
    value = int(token)
    if value < low or value > high:
        raise ValueError(
            f"{field} value {value} out of range ({low}-{high})"
        )
    return value


def _parse_field(text: str, low: int, high: int,
                 names: dict[str, int] | None, field: str) -> set[int]:
    """Expand one field into the set of values it matches."""
    values: set[int] = set()
    for item in text.split(","):
        if not item:
            raise ValueError(f"empty item in {field} field")
        if item.count("/") > 1:
            raise ValueError(f"invalid {field} item: {item!r}")

        base, separator, step_text = item.partition("/")
        has_step = bool(separator)
        if has_step:
            if not _NUMBER.fullmatch(step_text):
                raise ValueError(f"invalid step in {field} item: {item!r}")
            step = int(step_text)
            if step <= 0:
                raise ValueError(f"step must be positive in {field} item: {item!r}")
        else:
            step = 1

        if not base:
            raise ValueError(f"invalid {field} item: {item!r}")

        if base == "*":
            start, end = low, high
        elif "-" in base:
            parts = base.split("-")
            if len(parts) != 2 or not parts[0] or not parts[1]:
                raise ValueError(f"invalid {field} range: {base!r}")
            start = _parse_value(parts[0], low, high, names, field)
            end = _parse_value(parts[1], low, high, names, field)
            if start > end:
                raise ValueError(f"invalid {field} range: {base!r}")
        else:
            start = _parse_value(base, low, high, names, field)
            # "N/S" means from N to the end of the field.
            end = high if has_step else start

        values.update(range(start, end + 1, step))
    return values


def _parse_expression(expression: str) -> tuple[
        set[int], set[int], set[int], set[int], set[int], bool, bool]:
    """Parse an expression into minute/hour/day/month/weekday sets."""
    if not isinstance(expression, str):
        raise ValueError("cron expression must be a string")
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError(
            f"cron expression must have five fields, got {len(fields)}"
        )

    minute_text, hour_text, dom_text, month_text, dow_text = fields
    minutes = _parse_field(minute_text, 0, 59, None, "minute")
    hours = _parse_field(hour_text, 0, 23, None, "hour")
    doms = _parse_field(dom_text, 1, 31, None, "day-of-month")
    months = _parse_field(month_text, 1, 12, _MONTH_NAMES, "month")
    dows = _parse_field(dow_text, 0, 7, _WEEKDAY_NAMES, "day-of-week")

    # Sunday is both 0 and 7; matching uses datetime's Sunday == 0 form.
    if 7 in dows:
        dows.add(0)

    # Vixie cron's OR rule is triggered by a field that is not exactly "*".
    return (minutes, hours, doms, months, dows,
            dom_text != "*", dow_text != "*")


def _add_years(moment: datetime, years: int) -> datetime:
    """``moment`` shifted by whole calendar years, clamping Feb 29."""
    year = moment.year + years
    if year > datetime.max.year:
        return datetime.max
    try:
        return moment.replace(year=year)
    except ValueError:  # February 29 in a non-leap target year.
        return moment.replace(year=year, day=28)


def _day_matches(day: date, doms: set[int], dows: set[int],
                 dom_restricted: bool, dow_restricted: bool) -> bool:
    dom_match = day.day in doms
    # Python's Monday is 0; cron's Sunday is 0.
    dow_match = (day.weekday() + 1) % 7 in dows
    if dom_restricted and dow_restricted:
        return dom_match or dow_match
    return dom_match and dow_match


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    (minutes, hours, doms, months, dows,
     dom_restricted, dow_restricted) = _parse_expression(expression)

    # The first whole minute strictly after ``after``.
    try:
